#include "can_v_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void can_v_combo_iterator_init (Combo_Iterator * const iter , SInt8 * bit , const Combo_Iterator_Mode iter_mode , const UInt8 num_bits , const UInt32 bits)
{
  iter->num_bits     = num_bits  ;
  iter->mode         = iter_mode ;
  iter->bits         = bits      ;
  iter->bits_shifted = 0         ;

  can_v_combo_iterator_next (iter , bit) ;
}

//--------------------------------------------------------------------------//

void can_v_combo_iterator_next (Combo_Iterator * const iter , SInt8 * const bit)
{
  *bit = -1 ;

  while (iter->bits_shifted < iter->num_bits)
    {
      if ((iter->bits & 1) == iter->mode)
        {
          *bit = iter->bits_shifted ;
        }

      iter->bits >>= 1 ;

      iter->bits_shifted ++ ;

      if (*bit != -1)
        {
          return ;
        }
    }
}

